import 'package:flutter/widgets.dart';
import 'app_localizations.dart';
import 'data_translations.dart';

class UiText {
  static String t(BuildContext context, String english) {
    final code = AppLocalizations.of(context).code;
    if (code == 'en') return english;
    return DataTranslations.translate(code, english) ??
        _phrases[code]?[english] ??
        _fromAppLocalizations(context, english) ??
        _generic(code, english) ??
        english;
  }

  static String? _fromAppLocalizations(BuildContext context, String english) {
    final key = _englishToKey[english];
    if (key == null) return null;
    final translated = AppLocalizations.of(context).t(key);
    return translated == key ? null : translated;
  }

  static String? _generic(String code, String english) {
    if (english == 'optional') {
      return {
        'ur': 'اختیاری', 'hi': 'वैकल्पिक', 'ar': 'اختياري', 'es': 'opcional', 'pt': 'opcional', 'fr': 'optionnel', 'de': 'optional', 'ru': 'необязательно', 'zh': '可选', 'tr': 'isteğe bağlı', 'id': 'opsional', 'bn': 'ঐচ্ছিক', 'fa': 'اختیاری', 'ms': 'pilihan'
      }[code];
    }
    if (english == 'categories') {
      return {'ur':'کیٹیگریز','hi':'श्रेणियाँ','ar':'فئات','es':'categorías','pt':'categorias','fr':'catégories','de':'Kategorien','ru':'категории','zh':'类别','tr':'kategoriler','id':'kategori','bn':'ক্যাটাগরি','fa':'دسته‌ها','ms':'kategori'}[code];
    }
    if (english == 'Time') {
      return {'ur':'وقت','hi':'समय','ar':'الوقت','es':'Tiempo','pt':'Tempo','fr':'Temps','de':'Zeit','ru':'Время','zh':'时间','tr':'Zaman','id':'Waktu','bn':'সময়','fa':'زمان','ms':'Masa'}[code];
    }
    if (english == 'Wrong') {
      return {'ur':'غلط','hi':'गलत','ar':'خطأ','es':'Incorrectas','pt':'Erradas','fr':'Faux','de':'Falsch','ru':'Ошибки','zh':'错误','tr':'Yanlış','id':'Salah','bn':'ভুল','fa':'غلط','ms':'Salah'}[code];
    }
    if (english == 'steps') {
      return {'ur':'مراحل','hi':'चरण','ar':'خطوات','es':'pasos','pt':'passos','fr':'étapes','de':'Schritte','ru':'шагов','zh':'步骤','tr':'adım','id':'langkah','bn':'ধাপ','fa':'مراحل','ms':'langkah'}[code];
    }
    if (english == 'components') {
      return {'ur':'کمپوننٹس','hi':'घटक','ar':'مكونات','es':'componentes','pt':'componentes','fr':'composants','de':'Komponenten','ru':'компонентов','zh':'组件','tr':'bileşen','id':'komponen','bn':'কম্পোনেন্ট','fa':'قطعات','ms':'komponen'}[code];
    }
    if (english.contains('Search')) {
      return _phrases[code]?['Search'] ?? english;
    }
    return null;
  }

