    "Create a job to track client details, site notes, materials, labor, photos, checklists and invoices.": "Tạo công việc để theo dõi chi tiết khách hàng, ghi chú tại địa điểm, vật liệu, nhân công, hình ảnh, danh sách kiểm tra và hóa đơn.",
    "Camera-assisted manual band picker for accurate 4-band and 5-band resistor decoding.": "Bộ chọn băng tần thủ công được hỗ trợ bởi máy ảnh để giải mã điện trở 4 băng tần và 5 băng tần chính xác.",
    "Contact / Tester Name (optional)": "Tên người liên hệ/người kiểm tra (tùy chọn)",
    "Tip: Add materials and labor items in the project detail screen before generating the invoice.": "Mẹo: Thêm vật liệu và hạng mục lao động vào màn hình chi tiết dự án trước khi tạo hóa đơn.",
