    "Safety note: Electrical work must follow latest official code, utility requirements, manufacturer instructions, and qualified professional judgment.": "பாதுகாப்புக் குறிப்பு: மின் வேலைகள் சமீபத்திய அதிகாரப்பூர்வ குறியீடு, பயன்பாட்டுத் தேவைகள், உற்பத்தியாளர் அறிவுறுத்தல்கள் மற்றும் தகுதிவாய்ந்த தொழில்முறை தீர்ப்பு ஆகியவற்றைப் பின்பற்ற வேண்டும்.",
