    "Structured study tracks with modules, recommended content and track exams.": "ਮੌਡਿਊਲਾਂ, ਸਿਫ਼ਾਰਿਸ਼ ਕੀਤੀ ਸਮੱਗਰੀ ਅਤੇ ਟ੍ਰੈਕ ਪ੍ਰੀਖਿਆਵਾਂ ਦੇ ਨਾਲ ਸਟ੍ਰਕਚਰਡ ਸਟੱਡੀ ਟਰੈਕ।",
    "Create a job to track client details, site notes, materials, labor, photos, checklists and invoices.": "ਕਲਾਇੰਟ ਦੇ ਵੇਰਵਿਆਂ, ਸਾਈਟ ਨੋਟਸ, ਸਮੱਗਰੀ, ਲੇਬਰ, ਫੋਟੋਆਂ, ਚੈਕਲਿਸਟਾਂ ਅਤੇ ਇਨਵੌਇਸਾਂ ਨੂੰ ਟਰੈਕ ਕਰਨ ਲਈ ਇੱਕ ਨੌਕਰੀ ਬਣਾਓ।",
    "Contact / Tester Name (optional)": "ਸੰਪਰਕ / ਟੈਸਟਰ ਦਾ ਨਾਮ (ਵਿਕਲਪਿਕ)",
    "Camera-assisted manual band picker for accurate 4-band and 5-band resistor decoding.": "ਸਟੀਕ 4-ਬੈਂਡ ਅਤੇ 5-ਬੈਂਡ ਰੋਧਕ ਡੀਕੋਡਿੰਗ ਲਈ ਕੈਮਰਾ-ਸਹਾਇਤਾ ਵਾਲਾ ਮੈਨੂਅਲ ਬੈਂਡ ਪਿਕਰ।",
    "Tip: Add materials and labor items in the project detail screen before generating the invoice.": "ਸੁਝਾਅ: ਇਨਵੌਇਸ ਬਣਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਪ੍ਰੋਜੈਕਟ ਵੇਰਵੇ ਸਕ੍ਰੀਨ ਵਿੱਚ ਸਮੱਗਰੀ ਅਤੇ ਲੇਬਰ ਆਈਟਮਾਂ ਸ਼ਾਮਲ ਕਰੋ।",
    "Safety note: Electrical work must follow latest official code, utility requirements, manufacturer instructions, and qualified professional judgment.": "ਸੁਰੱਖਿਆ ਨੋਟ: ਇਲੈਕਟ੍ਰੀਕਲ ਕੰਮ ਨੂੰ ਨਵੀਨਤਮ ਅਧਿਕਾਰਤ ਕੋਡ, ਉਪਯੋਗਤਾ ਲੋੜਾਂ, ਨਿਰਮਾਤਾ ਨਿਰਦੇਸ਼ਾਂ, ਅਤੇ ਯੋਗ ਪੇਸ਼ੇਵਰ ਨਿਰਣੇ ਦੀ ਪਾਲਣਾ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ।",
    "Welcome Back,": "ਵਾਪਸ ਸਵਾਗਤ,",
    "Daily Safety Tip": "ਰੋਜ਼ਾਨਾ ਸੁਰੱਖਿਆ ਸੁਝਾਅ"
  },
